<script lang="ts">
  import {estimateTrainingMemory,estimateTrainingScale,quantizeScalar,type OptimizerMemory,type ShardingStrategy} from '../../lib/curriculum';
  type Stability = 'healthy' | 'exploding' | 'stalled';
  let stability:Stability='healthy',value=.63,quantStep=.25,qat=false,quantized=0,error=0;
  let parametersMillions=100,microBatch=8,savedActivationMillions=20,activationBits:16|32=16,optimizer:OptimizerMemory='adam',devices=4,strategy:ShardingStrategy='ddp',reservePercent=15,accumulationSteps=1,microStepMilliseconds=100,datasetExamples=100000;
  const curves:Record<Stability,number[]>={healthy:[1.15,.92,.76,.64,.54,.47,.41,.36,.32,.29,.27],exploding:[1.05,.88,.79,.95,.72,1.18,.84,1.55,1.12,1.9,2.35],stalled:[1.08,1.03,1.01,1,.99,.99,.98,.98,.98,.98,.98]};
  const diagnoses:Record<Stability,string>={healthy:'Finite gradients, a downward trend, and no widening train/validation gap.',exploding:'Spikes or non-finite values: inspect the learning rate, inputs, normalization, and gradient norm.',stalled:'Little movement: check data and labels, frozen parameters, gradient scale, and learning rate.'};
  const x=(i:number)=>36+i*45,y=(v:number)=>178-Math.min(v,2.5)/2.5*140;
  $: path=curves[stability].map((v,i)=>`${i?'L':'M'} ${x(i)} ${y(v)}`).join(' ');
  $: memory=estimateTrainingMemory({parametersMillions:Math.max(0,+parametersMillions||0),microBatch:Math.max(1,+microBatch||1),savedActivationMillionsPerSample:Math.max(0,+savedActivationMillions||0),activationBits:+activationBits as 16|32,optimizer,devices:Math.max(1,+devices||1),strategy,reservePercent:Math.max(0,+reservePercent||0)});
  $: scale=estimateTrainingScale({datasetExamples:Math.max(1,+datasetExamples||1),microBatch:Math.max(1,+microBatch||1),devices:Math.max(1,+devices||1),accumulationSteps:Math.max(1,+accumulationSteps||1),microStepMilliseconds:Math.max(1,+microStepMilliseconds||1)});
  $: ({quantized,error}=quantizeScalar(+value,+quantStep));
</script>
<section class="lab" aria-labelledby="constraints-title">
  <header><div><span>Systems lab</span><h3 id="constraints-title">Three budgets govern a training run</h3></div><p>numerical range · bytes · time</p></header>
  <article class="panel stability"><div class="copy"><small>1 · numerical health</small><h4>Would you trust this loss curve?</h4><div class="switch">{#each ['healthy','exploding','stalled'] as item}<button class:active={stability===item} onclick={()=>stability=item as Stability}>{item}</button>{/each}</div><p>{diagnoses[stability]}</p></div><svg viewBox="0 0 520 210" role="img" aria-label={`${stability} loss curve`}><line x1="36" y1="178" x2="492" y2="178"/><line x1="36" y1="25" x2="36" y2="178"/><path d={path}/><text x="40" y="20">loss</text><text x="447" y="200">steps</text></svg></article>
  <article class="panel memory">
    <div class="copy"><small>2 · scale-up planner</small><h4>What must fit on each device?</h4><p>Estimate persistent model state and saved activations separately. The calculator assumes FP32 parameters and gradients, then applies the selected optimizer and sharding strategy.</p></div>
    <div class="planner">
      <div class="planner-controls">
        <label>parameters <span><input type="number" min="1" step="25" bind:value={parametersMillions}/> M</span></label>
        <label>micro-batch / device <input type="number" min="1" max="512" bind:value={microBatch}/></label>
        <label>saved activations / sample <span><input type="number" min=".1" step="1" bind:value={savedActivationMillions}/> M elements</span></label>
        <label>activation precision <select bind:value={activationBits}><option value={32}>FP32 · 4 B</option><option value={16}>FP16/BF16 · 2 B</option></select></label>
        <label>optimizer <select bind:value={optimizer}><option value="sgd">SGD · no state</option><option value="momentum">SGD momentum · 4 B/param</option><option value="adam">Adam/AdamW · 8 B/param</option></select></label>
        <label>devices <input type="number" min="1" max="64" bind:value={devices}/></label>
        <label>distribution <select bind:value={strategy}><option value="ddp">DDP · replicate state</option><option value="zero1">ZeRO-1 · shard optimizer</option><option value="zero2">ZeRO-2 · + gradients</option><option value="zero3">ZeRO-3 · + parameters</option></select></label>
        <label>planning reserve <span><input type="number" min="0" max="50" step="5" bind:value={reservePercent}/> %</span></label>
      </div>
      <div class="estimate">
        <div class="estimate-head"><span>estimated peak / device</span><strong>{memory.total.toFixed(2)} GiB</strong></div>
        <div class="stacked" aria-label="Estimated memory breakdown"><i class="weights" style={`--size:${memory.weights}`}></i><i class="gradients" style={`--size:${memory.gradients}`}></i><i class="optimizer" style={`--size:${memory.optimizer}`}></i><i class="activations" style={`--size:${memory.activations}`}></i><i class="reserve" style={`--size:${memory.reserve}`}></i></div>
        <div class="legend"><span><i class="weights"></i>parameters <b>{memory.weights.toFixed(2)}</b></span><span><i class="gradients"></i>gradients <b>{memory.gradients.toFixed(2)}</b></span><span><i class="optimizer"></i>optimizer <b>{memory.optimizer.toFixed(2)}</b></span><span><i class="activations"></i>activations <b>{memory.activations.toFixed(2)}</b></span><span><i class="reserve"></i>reserve <b>{memory.reserve.toFixed(2)}</b></span></div>
        <div class="formula"><code>M<sub>params</sub> = P × 4 B ÷ parameter shards</code><code>M<sub>grads</sub> = P × 4 B ÷ gradient shards</code><code>M<sub>opt</sub> = P × {memory.optimizerBytesPerParameter} B ÷ optimizer shards</code><code>M<sub>act</sub> ≈ micro-batch × saved elements/sample × {activationBits/8} B</code></div>
      </div>
    </div>
    <div class="scale-controls"><label>gradient accumulation <input type="number" min="1" max="64" bind:value={accumulationSteps}/></label><label>measured micro-step <span><input type="number" min="1" bind:value={microStepMilliseconds}/> ms</span></label><label>dataset <span><input type="number" min="1" step="10000" bind:value={datasetExamples}/> examples</span></label></div>
    <div class="scale-results"><span>global batch<b>{scale.globalBatch}</b><code>{microBatch} × {devices} × {accumulationSteps}</code></span><span>optimizer steps / epoch<b>{scale.optimizerStepsPerEpoch.toLocaleString()}</b><code>ceil(N ÷ global batch)</code></span><span>ideal throughput<b>{scale.throughput.toFixed(0)}/s</b><code>global batch ÷ update time</code></span><span>ideal time / epoch<b>{(scale.epochSeconds/60).toFixed(1)} min</b><code>steps × update time</code></span></div>
    <footer class="assumption">Planning estimate only: buffers, temporary kernels, communication buckets, compilation, and fragmentation vary by model and hardware. Confirm with a small measured run.</footer>
  </article>
  <article class="panel quantization"><div class="copy"><small>3 · representational error</small><h4>When does rounding become part of learning?</h4><p>Post-training quantization changes inference after training. Quantization-aware training inserts simulated rounding in the forward pass so the model can adapt before export.</p><button class:active={qat} onclick={()=>qat=!qat}>{qat?'QAT: simulated during training':'PTQ: applied after training'}</button></div><div class="number-line"><div class="values"><span>original <b>{(+value).toFixed(2)}</b></span><span>stored level <b>{quantized.toFixed(2)}</b></span><span>error <b>{error>=0?'+':''}{error.toFixed(2)}</b></span></div><div class="track"><i class="original" style={`left:${(+value)*100}%`}></i><i class="rounded" style={`left:${quantized*100}%`}></i></div><label>value <input type="range" min="0" max="1" step=".01" bind:value={value}/></label><label>quantization step <b>{(+quantStep).toFixed(2)}</b><input type="range" min=".05" max=".5" step=".05" bind:value={quantStep}/></label><footer>{qat?'Forward: fake quantization exposes rounding error. Backward: a surrogate gradient keeps learning possible.':'Training remains full precision; rounding error appears only in the exported inference model.'}</footer></div></article>
</section>
<style>
  .lab{margin:2rem 0;border:1px solid var(--border);border-radius:16px;background:var(--surface);overflow:hidden;box-shadow:0 16px 45px var(--shadow)}header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.1rem;border-bottom:1px solid var(--border)}header span,.copy small{font:800 .58rem var(--font-mono);text-transform:uppercase;letter-spacing:.1em;color:var(--accent)}header h3{margin:.2rem 0}header p{margin:0;color:var(--text-muted);font:.61rem var(--font-mono)}.panel{display:grid;grid-template-columns:.9fr 1.3fr;border-bottom:1px solid var(--border)}.panel:last-child{border:0}.copy{padding:1rem}.copy h4{margin:.25rem 0 .6rem}.copy p{color:var(--text-muted);font-size:.66rem;line-height:1.55}.switch{display:flex}.copy button{border:1px solid var(--border);background:var(--bg);color:var(--text);padding:.4rem .55rem;font-size:.61rem}.copy button.active{background:var(--accent);border-color:var(--accent);color:white}.stability svg{width:100%;align-self:center;background:#121925}.stability line{stroke:#536075}.stability path{fill:none;stroke:#df7656;stroke-width:3}.stability text{fill:#9aa6b6;font:10px var(--font-mono)}.memory{display:block;background:#121925;color:white}.memory>.copy{background:var(--surface);color:var(--text)}.planner{display:grid;grid-template-columns:.8fr 1.2fr;border-top:1px solid #303949}.planner-controls{display:grid;grid-template-columns:1fr 1fr;gap:.65rem;padding:1rem;border-right:1px solid #303949}.planner-controls label,.scale-controls label{display:flex;flex-direction:column;gap:.25rem;color:#9ba7b7;font-size:.55rem}.planner-controls input,.planner-controls select,.scale-controls input{box-sizing:border-box;width:100%;border:1px solid #3d495b;border-radius:4px;background:#182230;color:white;padding:.38rem;font:inherit}.planner-controls label span,.scale-controls label span{display:flex;align-items:center;gap:.3rem;white-space:nowrap}.estimate{padding:1rem}.estimate-head{display:flex;justify-content:space-between;align-items:end}.estimate-head span{color:#99a5b5;font-size:.56rem}.estimate-head strong{font:800 1.15rem var(--font-mono);color:#ff9b79}.stacked{display:flex;height:30px;margin:.65rem 0;border:1px solid #485468;border-radius:5px;overflow:hidden}.stacked i{display:block;flex-grow:var(--size);min-width:1px}.weights{background:#7890b2}.gradients{background:#a5b4c8}.optimizer{background:#df7656}.activations{background:#d2a65f}.reserve{background:#657184}.legend{display:grid;grid-template-columns:1fr 1fr;gap:.35rem}.legend span{display:grid;grid-template-columns:9px 1fr auto;align-items:center;gap:.3rem;color:#9ca8b8;font-size:.52rem}.legend i{width:8px;height:8px;border-radius:2px}.legend b{color:white;font:600 .56rem var(--font-mono)}.formula{display:grid;gap:.28rem;margin-top:.75rem;padding-top:.65rem;border-top:1px solid #303949}.formula code{color:#aeb8c6;font-size:.53rem}.scale-controls{display:grid;grid-template-columns:repeat(3,1fr);gap:.7rem;padding:.8rem 1rem;border-top:1px solid #303949}.scale-results{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#303949}.scale-results span{padding:.7rem;background:#182230;color:#9da9b9;font-size:.52rem}.scale-results b,.scale-results code{display:block}.scale-results b{margin:.2rem 0;color:white;font:.78rem var(--font-mono)}.scale-results code{color:#78879b;font-size:.48rem}.assumption{padding:.65rem 1rem;color:#8996a8;font-size:.55rem}.number-line{padding:1rem;background:#121925;color:white}.values{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}.values span{padding:.55rem;border:1px solid #344054;color:#9aa6b6;font-size:.58rem}.values b{display:block;color:white;font:.75rem var(--font-mono)}.track{position:relative;height:4px;margin:2.2rem .6rem;background:#526076}.track i{position:absolute;top:50%;width:14px;height:14px;transform:translate(-50%,-50%);border-radius:50%}.track .original{background:#8ea6ca}.track .rounded{border:3px solid #df7656}.number-line label{display:grid;grid-template-columns:1fr auto;color:#aab4c3;font-size:.61rem}.number-line input{grid-column:1/-1;accent-color:#df7656}.number-line footer{margin-top:.8rem;padding:.6rem;background:#1d2735;color:#aab4c3;font-size:.61rem}@media(max-width:700px){header{align-items:flex-start;gap:.5rem;flex-direction:column}.panel{grid-template-columns:1fr}.stability svg{min-height:210px}.planner{grid-template-columns:1fr}.planner-controls{border-right:0;border-bottom:1px solid #303949}.scale-results{grid-template-columns:1fr 1fr}.values{grid-template-columns:1fr 1fr}.values span:last-child{grid-column:1/-1}}@media(max-width:450px){.planner-controls,.scale-controls{grid-template-columns:1fr}.scale-results{grid-template-columns:1fr}}
</style>
